"use strict";(self.webpackChunkquickbooks_connector_doc=self.webpackChunkquickbooks_connector_doc||[]).push([[87],{5567(e,o,t){t.r(o),t.d(o,{comp:()=>r,data:()=>s});var n=t(641);const i={},r=(0,t(6262).A)(i,[["render",function(e,o){const t=(0,n.g2)("RouteLink");return(0,n.uX)(),(0,n.CE)("div",null,[o[3]||(o[3]=(0,n.Fv)('<h1 id="features" tabindex="-1"><a class="header-anchor" href="#features"><span>Features</span></a></h1><p>Every feature below is available from <strong>Webkul WC Addons → WC Quick Book Connector</strong> in your WordPress admin.</p><hr><h2 id="connection-onboarding" tabindex="-1"><a class="header-anchor" href="#connection-onboarding"><span>Connection &amp; Onboarding</span></a></h2><ul><li>Guided four-step <strong>Setup Wizard</strong> (Welcome → Environment → Credentials → Ready) with Skip option</li><li><strong>Sandbox / Development</strong> and <strong>Live / Production</strong> environment modes</li><li><strong>OAuth 2.0</strong> authorization (recommended) with legacy OAuth 1.0 selectable</li><li>One-click <strong>Connect with QuickBooks</strong> — Company ID, access token, and refresh token fetched automatically</li><li>Built-in <strong>connection test</strong> that verifies credentials before saving them</li><li>Connection dashboard with status badges, masked credentials, and token status</li><li><strong>Edit credentials</strong>, <strong>Re-run Setup Wizard</strong>, and <strong>Delete Credentials</strong> (with confirmation) at any time</li><li>Copyable <strong>Redirect URIs</strong> for your Intuit Developer app</li></ul><h2 id="customer-sync" tabindex="-1"><a class="header-anchor" href="#customer-sync"><span>Customer Sync</span></a></h2><ul><li><strong>Export Customers</strong> from WooCommerce to QuickBooks (selected rows)</li><li><strong>Import Customers</strong> from QuickBooks into WooCommerce</li><li>Per-customer mapping dropdown with live QuickBooks customer search</li><li>Clear a customer&#39;s mapping without touching the customer record</li><li>Search customers by email; adjustable rows per page</li></ul><h2 id="product-sync" tabindex="-1"><a class="header-anchor" href="#product-sync"><span>Product Sync</span></a></h2><ul><li><strong>Export Products</strong> to QuickBooks — variable products export each variation</li><li>Two-step import: <strong>Import List</strong> stages QuickBooks items, <strong>Create Products</strong> builds them in WooCommerce</li><li>Batch-size control (3–30) with resumable import position</li><li>Duplicate-SKU protection with a live &quot;products skipped&quot; counter</li><li>Real-time export on product save, filtered by product category</li><li>Real-time import via QuickBooks webhooks, filtered by QuickBooks category</li><li>Product <strong>image sync</strong> in either direction</li><li>Per-product mapping dropdown, Clear Mapping, and sync-source badge</li><li>Optional export of zero-price products</li></ul><h2 id="order-sync-accounting" tabindex="-1"><a class="header-anchor" href="#order-sync-accounting"><span>Order Sync &amp; Accounting</span></a></h2><ul><li><strong>Export Orders</strong> manually from the Orders tab</li><li><strong>Auto Export Orders</strong> when an order reaches a chosen status (Pending, Processing, On hold, Completed, or All)</li><li>Export orders as <strong>Sales Receipt, Invoice, Estimate, or Credit Memo</strong></li><li><strong>Void</strong> the QuickBooks transaction when a WooCommerce order is cancelled</li><li><strong>Refund receipts</strong> created automatically for WooCommerce refunds</li><li>Choose the QuickBooks transaction date (order date, paid date, complete date, or sync date)</li><li>Choose the line-item description (product name, description, or short description)</li><li>Payment reference number from order number or transaction ID</li><li>Statement memo, service date, print status, and skip-country options</li><li>Default QuickBooks <strong>Class</strong> and <strong>Department</strong> for exported orders</li><li>Sync status pill per order, search by order ID, and <strong>POS / WooCommerce source filter</strong></li><li><strong>QuickBooks column</strong> on the WooCommerce Orders screen showing export status at a glance</li></ul><h2 id="payments-fees-deposits" tabindex="-1"><a class="header-anchor" href="#payments-fees-deposits"><span>Payments, Fees &amp; Deposits</span></a></h2><ul><li>Map every enabled WooCommerce gateway to a QuickBooks payment method</li><li>Per-gateway <strong>Advanced Configuration</strong>: <ul><li>Payment sync timing — when the order is received or completed</li><li>Target QuickBooks <strong>bank account</strong> and invoice due days (0–100)</li><li><strong>Transaction fee</strong> syncing with a QuickBooks VAT rate and expense account</li><li>Stripe-specific: record fees as an <strong>Expense or Journal Entry</strong> with a payee supplier</li><li><strong>Batch bank deposits</strong> from Undeposited Funds on a weekly schedule (day + hour)</li><li>Per-gateway QuickBooks class and department</li></ul></li></ul><h2 id="tax-mapping" tabindex="-1"><a class="header-anchor" href="#tax-mapping"><span>Tax Mapping</span></a></h2><ul><li>Map each WooCommerce tax class to a QuickBooks tax name</li><li>Default tax code for records without a specific mapping</li><li>Clear a tax mapping at any time</li></ul><h2 id="automation-housekeeping" tabindex="-1"><a class="header-anchor" href="#automation-housekeeping"><span>Automation &amp; Housekeeping</span></a></h2><ul><li>QuickBooks <strong>webhooks</strong> (items, invoices, bills, payments) processed asynchronously</li><li>Background schedules keep recently changed QuickBooks items updated in WooCommerce</li><li>Weekly per-gateway deposit schedules</li><li>Detailed activity logs in <strong>WooCommerce → Status → Logs</strong></li><li><strong>Need Help?</strong> menu with user guide, video, and support desk links</li></ul><hr>',18)),(0,n.Lk)("p",null,[o[1]||(o[1]=(0,n.Lk)("strong",null,"Next step:",-1)),o[2]||(o[2]=(0,n.eW)()),(0,n.bF)(t,{to:"/quickbooks-connector/installation.html"},{default:(0,n.k6)(()=>[...o[0]||(o[0]=[(0,n.eW)("Installation →",-1)])]),_:1})])])}]]),s=JSON.parse('{"path":"/quickbooks-connector/features.html","title":"Features","lang":"en-US","frontmatter":{"title":"Features","description":"Full feature list of the WooCommerce QuickBooks Connector — connection, sync, mapping, automation, and order accounting features."},"headers":[{"level":2,"title":"Connection & Onboarding","slug":"connection-onboarding","link":"#connection-onboarding","children":[]},{"level":2,"title":"Customer Sync","slug":"customer-sync","link":"#customer-sync","children":[]},{"level":2,"title":"Product Sync","slug":"product-sync","link":"#product-sync","children":[]},{"level":2,"title":"Order Sync & Accounting","slug":"order-sync-accounting","link":"#order-sync-accounting","children":[]},{"level":2,"title":"Payments, Fees & Deposits","slug":"payments-fees-deposits","link":"#payments-fees-deposits","children":[]},{"level":2,"title":"Tax Mapping","slug":"tax-mapping","link":"#tax-mapping","children":[]},{"level":2,"title":"Automation & Housekeeping","slug":"automation-housekeeping","link":"#automation-housekeeping","children":[]}],"git":{},"filePathRelative":"quickbooks-connector/features.md"}')}}]);